def compute(vars):
    current_commitment = vars["v1"]
    total_commitment = vars["v2"]

    if total_commitment == 0:
        return None

    ratio = current_commitment / total_commitment
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "current_commitment": current_commitment,
            "total_commitment": total_commitment,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
